import{_ as c,I as s,o as p,c as u,b6 as n,j as e,J as o,w as t,a as i}from"./chunks/framework.BUXTSoD9.js";const x=JSON.parse('{"title":"Desarrollo Practico: Plataforma de Agentes Inteligentes tipo Dify","description":"","frontmatter":{},"headers":[],"relativePath":"es-es/stage-2/assignments/custom-dify-agent-platform/index.md","filePath":"es-es/stage-2/assignments/custom-dify-agent-platform/index.md"}'),g={name:"es-es/stage-2/assignments/custom-dify-agent-platform/index.md"},m={style:{margin:"32px 0"}};function h(b,a,f,y,k,v){const r=s("StepBar"),l=s("ClientOnly"),d=s("el-card");return p(),u("div",null,[a[2]||(a[2]=n('<h1 id="desarrollo-practico-plataforma-de-agentes-inteligentes-tipo-dify" tabindex="-1">Desarrollo Practico: Plataforma de Agentes Inteligentes tipo Dify <a class="header-anchor" href="#desarrollo-practico-plataforma-de-agentes-inteligentes-tipo-dify" aria-label="Permalink to “Desarrollo Practico: Plataforma de Agentes Inteligentes tipo Dify”">​</a></h1><h2 id="descripcion-general" tabindex="-1">Descripcion general <a class="header-anchor" href="#descripcion-general" aria-label="Permalink to “Descripcion general”">​</a></h2><p>Este proyecto practico te requiere trabajar con un PRD real para completar desde cero una plataforma de agentes inteligentes que replica la experiencia central de Dify. Construiras una consola de usuario, un panel de administracion y un backend de plataforma, implementando funcionalidades principales como gestion de agentes, conversacion, logs y base de conocimientos.</p><p>Esta es la seccion de practica integral de la Etapa 2. A diferencia de los proyectos anteriores de pagina unica o funcion unica, este proyecto te exige construir un producto de IA con &quot;sensacion de plataforma&quot;, que incluye multiples roles, multiples modulos, persistencia de datos y un pipeline de llamadas a modelos.</p><h2 id="conocimientos-previos" tabindex="-1">Conocimientos previos <a class="header-anchor" href="#conocimientos-previos" aria-label="Permalink to “Conocimientos previos”">​</a></h2><p>Antes de comenzar este proyecto, ya deberias dominar lo siguiente:</p><ul><li>Diseno de paginas frontend y uso de bibliotecas de componentes (<a href="./../../frontend/ui-design/">Diseno UI</a>, <a href="./../../frontend/modern-component-library/">Biblioteca de componentes moderna</a>)</li><li>Diseno y desarrollo de interfaces backend (<a href="./../../backend/ai-interface-code/">Escritura de codigo de interfaces</a>)</li><li>Fundamentos de bases de datos y Supabase (<a href="./../../backend/database-supabase/">De la base de datos a Supabase</a>)</li><li>Flujo de trabajo de Git y despliegue (<a href="./../../backend/git-workflow/">Git y GitHub</a>, <a href="./../../backend/zeabur-deployment/">Despliegue de aplicaciones web</a>)</li></ul><h2 id="objetivos-de-aprendizaje" tabindex="-1">Objetivos de aprendizaje <a class="header-anchor" href="#objetivos-de-aprendizaje" aria-label="Permalink to “Objetivos de aprendizaje”">​</a></h2><p>Despues de completar esta practica, podras:</p><ol><li>Leer y comprender un PRD real, extrayendo una lista de tareas de desarrollo</li><li>Disenar la arquitectura de paginas y el modelo de datos de una plataforma de agentes</li><li>Implementar el ciclo completo de creacion de agentes, conversacion y registro de logs</li><li>Usar IA para asistir en el desarrollo de productos tipo plataforma</li><li>Completar la integracion de extremo a extremo, entregando un prototipo de plataforma de IA demostrable</li></ol><h2 id="introduccion-del-proyecto" tabindex="-1">Introduccion del proyecto <a class="header-anchor" href="#introduccion-del-proyecto" aria-label="Permalink to “Introduccion del proyecto”">​</a></h2><p>El producto que vas a construir es una plataforma de agentes inteligentes tipo Dify, que incluye dos subsistemas:</p><table tabindex="0"><thead><tr><th>Subsistema</th><th>Responsabilidad</th></tr></thead><tbody><tr><td><strong>Consola de usuario</strong></td><td>Crear agentes, configurar Prompt, iniciar conversaciones, ver logs, gestionar base de conocimientos</td></tr><tr><td><strong>Panel de administracion</strong></td><td>Ver datos de usuarios, uso de recursos de la plataforma, estadisticas de llamadas</td></tr></tbody></table><p>El backend necesita soportar las siguientes capacidades principales: gestion de agentes, gestion de sesiones, almacenamiento de mensajes, llamadas a modelos, registro de logs de llamadas e integracion de base de conocimientos.</p><div class="tip custom-block"><p class="custom-block-title">PRD</p><p>El documento de requisitos de este proyecto esta en GitHub: <a href="https://github.com/datawhalechina/easy-vibe/blob/main/docs/es-es/stage-2/assignments/custom-dify-agent-platform/PRD.md" target="_blank" rel="noreferrer">Ver PRD</a></p></div>',15)),e("div",m,[o(l,null,{default:t(()=>[o(r,{active:0,items:[{title:"Analisis de requisitos",description:"Leer el PRD, definir paginas, limites de capacidades, autenticacion y modelo de datos"},{title:"Construccion del esqueleto",description:"Usar IA para generar los esqueletos de la consola de usuario y el panel de administracion"},{title:"Desarrollo iterativo",description:"Agregar agentes, conversacion, logs y base de conocimientos modulo por modulo"},{title:"Integracion y despliegue",description:"Verificar de extremo a extremo, desplegar y preparar la demostracion"}]})]),_:1})]),a[3]||(a[3]=n(`<h2 id="primera-parte-analisis-de-requisitos" tabindex="-1">Primera parte: Analisis de requisitos <a class="header-anchor" href="#primera-parte-analisis-de-requisitos" aria-label="Permalink to “Primera parte: Analisis de requisitos”">​</a></h2><h3 id="_1-1-leer-el-prd" tabindex="-1">1.1 Leer el PRD <a class="header-anchor" href="#_1-1-leer-el-prd" aria-label="Permalink to “1.1 Leer el PRD”">​</a></h3><p>Abre el documento PRD y responde las siguientes preguntas clave:</p><ul><li>Que elementos deben incluirse en el MVP: agentes, sesiones, logs, base de conocimientos?</li><li>La lista de paginas y rutas esta definida?</li><li>Cual es el alcance de las llamadas a modelos y el registro de logs?</li><li>Multi-tenencia y flujos de trabajo complejos deben excluirse en la primera version?</li></ul><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>Si no tienes respuestas claras a las preguntas anteriores, no comiences a escribir codigo. La comprension inadecuada de los requisitos es la causa mas comun de retrabajo.</p></div><h3 id="_1-2-confirmar-la-arquitectura-del-sistema" tabindex="-1">1.2 Confirmar la arquitectura del sistema <a class="header-anchor" href="#_1-2-confirmar-la-arquitectura-del-sistema" aria-label="Permalink to “1.2 Confirmar la arquitectura del sistema”">​</a></h3><p>Segun el PRD, organiza la arquitectura general del sistema:</p><div class="language-mermaid"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd[&quot;PRD&quot;] --&gt; app[&quot;Consola de usuario&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd --&gt; admin[&quot;Panel de administracion&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  app --&gt; auth[&quot;Autenticacion&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  app --&gt; agent[&quot;Configuracion del agente&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  app --&gt; chat[&quot;Sesion de conversacion&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  chat --&gt; llm[&quot;Llamada al modelo&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  chat --&gt; db[&quot;Base de datos&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  app --&gt; kb[&quot;Integracion de base de conocimientos&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  admin --&gt; logs[&quot;Logs de llamadas y resumen de plataforma&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  logs --&gt; db</span></span></code></pre></div><h2 id="segunda-parte-construccion-del-esqueleto-del-proyecto" tabindex="-1">Segunda parte: Construccion del esqueleto del proyecto <a class="header-anchor" href="#segunda-parte-construccion-del-esqueleto-del-proyecto" aria-label="Permalink to “Segunda parte: Construccion del esqueleto del proyecto”">​</a></h2><h3 id="_2-1-generar-paginas-frontend" tabindex="-1">2.1 Generar paginas frontend <a class="header-anchor" href="#_2-1-generar-paginas-frontend" aria-label="Permalink to “2.1 Generar paginas frontend”">​</a></h3><p>Referencia de prompts:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Basandote en el PRD actual, ayudame a generar el esqueleto frontend de una plataforma de agentes inteligentes tipo Dify.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Requisitos:</span></span>
<span class="line"><span>1. El lado del usuario incluye: inicio de sesion, lista de agentes, configuracion del agente, pagina de conversacion, pagina de logs, pagina de base de conocimientos</span></span>
<span class="line"><span>2. El lado del administrador incluye: pagina principal del panel, resumen de usuarios, resumen de uso de recursos</span></span>
<span class="line"><span>3. Primero generar solo la estructura de paginas y datos ficticios, sin conectar interfaces reales</span></span>
<span class="line"><span>4. El estilo debe parecerse a una plataforma de IA moderna</span></span></code></pre></div><h3 id="_2-2-verificar-la-estructura-de-paginas" tabindex="-1">2.2 Verificar la estructura de paginas <a class="header-anchor" href="#_2-2-verificar-la-estructura-de-paginas" aria-label="Permalink to “2.2 Verificar la estructura de paginas”">​</a></h3><p>Verificar item por item:</p><ul><li>[ ] Los puntos de entrada de la consola de usuario y el panel de administracion estan separados</li><li>[ ] Las paginas de lista de agentes, configuracion, conversacion, logs y base de conocimientos estan completas</li><li>[ ] La pagina principal del panel de administracion y el resumen de usuarios son accesibles</li><li>[ ] Los datos ficticios muestran estados basicos de la interfaz</li></ul><h2 id="tercera-parte-desarrollo-iterativo" tabindex="-1">Tercera parte: Desarrollo iterativo <a class="header-anchor" href="#tercera-parte-desarrollo-iterativo" aria-label="Permalink to “Tercera parte: Desarrollo iterativo”">​</a></h2><h3 id="_3-1-avanzar-por-modulos" tabindex="-1">3.1 Avanzar por modulos <a class="header-anchor" href="#_3-1-avanzar-por-modulos" aria-label="Permalink to “3.1 Avanzar por modulos”">​</a></h3><p>Sobre la base del esqueleto, agrega funcionalidades modulo por modulo en el siguiente orden:</p><ol><li><strong>Autenticacion</strong>: Registro, inicio de sesion, diferenciacion de roles</li><li><strong>Gestion de agentes</strong>: Crear, editar, eliminar, configuracion de Prompt</li><li><strong>Funcionalidad de conversacion</strong>: Creacion de sesiones, envio y recepcion de mensajes, llamadas a modelos</li><li><strong>Registro de logs</strong>: Tiempo de respuesta, uso de tokens, registro de errores</li><li><strong>Integracion de base de conocimientos</strong> (punto extra): Carga de documentos, busqueda, inyeccion de resultados</li><li><strong>Panel de administracion</strong>: Datos de usuarios, uso de recursos, estadisticas de llamadas</li></ol><p>Despues de completar cada modulo, usa la siguiente tabla para autoverificacion:</p><table tabindex="0"><thead><tr><th>Item de verificacion</th><th>Metodo de verificacion</th></tr></thead><tbody><tr><td>Consistencia de paginas</td><td>El numero de paginas y funcionalidades coincide con el PRD</td></tr><tr><td>Cierre de interfaces</td><td>Las interfaces de agents, chat, logs y knowledge estan completas</td></tr><tr><td>Aislamiento de permisos</td><td>Los usuarios solo pueden gestionar sus propios agentes y sesiones</td></tr><tr><td>Consistencia de datos</td><td>Los datos de messages, logs y documents coinciden</td></tr><tr><td>Demostrabilidad</td><td>Se puede demostrar el ciclo completo &quot;crear agente -&gt; conversar -&gt; ver logs&quot;</td></tr></tbody></table><h3 id="_3-2-integracion-de-base-de-conocimientos-punto-extra" tabindex="-1">3.2 Integracion de base de conocimientos (punto extra) <a class="header-anchor" href="#_3-2-integracion-de-base-de-conocimientos-punto-extra" aria-label="Permalink to “3.2 Integracion de base de conocimientos (punto extra)”">​</a></h3><p>Si deseas agregar capacidades de base de conocimientos, puedes anadir un &quot;interruptor de base de conocimientos&quot; para cada agente:</p><ul><li>Cuando esta activado, primero busca fragmentos de conocimiento y luego los envia junto con la pregunta del usuario al modelo</li><li>Cuando esta desactivado, responde en modo de conversacion normal</li></ul><p>La primera version no necesita implementar RAG complejo; basta con que los resultados de busqueda sean visibles y el pipeline de llamadas sea explicable.</p><h2 id="cuarta-parte-integracion-y-despliegue" tabindex="-1">Cuarta parte: Integracion y despliegue <a class="header-anchor" href="#cuarta-parte-integracion-y-despliegue" aria-label="Permalink to “Cuarta parte: Integracion y despliegue”">​</a></h2><h3 id="_4-1-pruebas-de-extremo-a-extremo" tabindex="-1">4.1 Pruebas de extremo a extremo <a class="header-anchor" href="#_4-1-pruebas-de-extremo-a-extremo" aria-label="Permalink to “4.1 Pruebas de extremo a extremo”">​</a></h3><p>Verificar al menos los siguientes escenarios:</p><ul><li>Registrarse -&gt; Crear agente -&gt; Configurar Prompt -&gt; Iniciar conversacion -&gt; Ver logs</li><li>Iniciar sesion como administrador -&gt; Ver datos de usuarios -&gt; Ver estadisticas de llamadas</li></ul><p>Verificacion antes del despliegue:</p><ul><li>[ ] Todas las interfaces principales tienen verificacion de inicio de sesion</li><li>[ ] La verificacion de pertenencia del agente ha pasado</li><li>[ ] Los registros de sesiones y logs se almacenan realmente en la base de datos</li><li>[ ] La clave del modelo usa variables de entorno, sin hardcoding</li><li>[ ] Los mensajes de error son visibles en el frontend, no solo en la consola</li></ul><h3 id="_4-2-despliegue" tabindex="-1">4.2 Despliegue <a class="header-anchor" href="#_4-2-despliegue" aria-label="Permalink to “4.2 Despliegue”">​</a></h3><p>Desplegar el proyecto en un entorno publico. Tutorial de despliegue de referencia: <a href="./../../backend/git-workflow/">Flujo de trabajo de Git y GitHub</a>, <a href="./../../backend/zeabur-deployment/">Despliegue de aplicaciones web</a>.</p><h2 id="entregables" tabindex="-1">Entregables <a class="header-anchor" href="#entregables" aria-label="Permalink to “Entregables”">​</a></h2><p>Despues de completar este proyecto, necesitas enviar lo siguiente:</p><ul><li>[ ] Enlace de demostracion en linea accesible</li><li>[ ] Enlace al repositorio de codigo fuente (incluyendo README)</li><li>[ ] Documento PRD</li><li>[ ] Capturas de pantalla de paginas clave (gestion de agentes, pagina de conversacion, pagina de logs, pagina principal del panel)</li><li>[ ] Video de demostracion de 60 segundos (cubriendo crear agente -&gt; conversar -&gt; ver logs)</li></ul><p>El README debe incluir al menos: introduccion del proyecto, descripcion de arquitectura, stack tecnologico, pasos de inicio local, lista de variables de entorno y descripcion de interfaces.</p><h2 id="criterios-de-evaluacion" tabindex="-1">Criterios de evaluacion <a class="header-anchor" href="#criterios-de-evaluacion" aria-label="Permalink to “Criterios de evaluacion”">​</a></h2><table tabindex="0"><thead><tr><th>Dimension</th><th>Requisitos basicos</th><th>Requisitos avanzados</th></tr></thead><tbody><tr><td>Completitud de plataforma</td><td>Las tres paginas de agents/chat/logs son funcionales</td><td>Tiene navegacion clara y lenguaje de diseno unificado</td></tr><tr><td>Ciclo completo del negocio</td><td>Se pueden crear agentes y tener conversaciones reales</td><td>Soporta cambio entre multiples agentes e historial de sesiones</td></tr><tr><td>Datos y seguimiento</td><td>Los mensajes y logs de llamadas son consultables</td><td>Tiene un dashboard de estadisticas de tokens y tiempo de respuesta</td></tr><tr><td>Seguridad de permisos</td><td>Solo usuarios autenticados pueden acceder a las interfaces principales</td><td>La verificacion de pertenencia de recursos es robusta</td></tr><tr><td>Entrega de ingenieria</td><td>Desplegable, demostrable, README claro</td><td>Integra base de conocimientos y puede explicar resultados de busqueda</td></tr></tbody></table><h2 id="verificacion-antes-de-enviar" tabindex="-1">Verificacion antes de enviar <a class="header-anchor" href="#verificacion-antes-de-enviar" aria-label="Permalink to “Verificacion antes de enviar”">​</a></h2>`,40)),o(d,{shadow:"hover",style:{margin:"20px 0","border-radius":"12px"}},{header:t(()=>[...a[0]||(a[0]=[e("div",{style:{"font-weight":"bold","font-size":"16px"}},"Revision final antes de enviar",-1)])]),default:t(()=>[a[1]||(a[1]=e("ul",{style:{"list-style-type":"none","padding-left":"0"}},[e("li",null,[e("label",null,[e("input",{type:"checkbox",disabled:""}),i(" Despues de iniciar sesion se puede acceder a las paginas de gestion de agentes, conversacion y logs")])]),e("li",null,[e("label",null,[e("input",{type:"checkbox",disabled:""}),i(" Se puede crear al menos 1 agente y conversar exitosamente")])]),e("li",null,[e("label",null,[e("input",{type:"checkbox",disabled:""}),i(" Cada ronda de preguntas y respuestas tiene registros en la base de datos")])]),e("li",null,[e("label",null,[e("input",{type:"checkbox",disabled:""}),i(" Cuando una llamada falla, el error es visible en el frontend y se registra en los logs")])]),e("li",null,[e("label",null,[e("input",{type:"checkbox",disabled:""}),i(" El proyecto esta desplegado, README y video de demostracion completos")])])],-1))]),_:1}),a[4]||(a[4]=n('<h2 id="referencias" tabindex="-1">Referencias <a class="header-anchor" href="#referencias" aria-label="Permalink to “Referencias”">​</a></h2><ul><li><a href="./../../frontend/ui-design/">Diseno UI</a></li><li><a href="./../../frontend/modern-component-library/">Biblioteca de componentes moderna</a></li><li><a href="./../../backend/database-supabase/">De la base de datos a Supabase</a></li><li><a href="./../../backend/ai-interface-code/">Escritura de codigo de interfaces</a></li><li><a href="./../../backend/git-workflow/">Flujo de trabajo de Git y GitHub</a></li><li><a href="./../../backend/zeabur-deployment/">Despliegue de aplicaciones web</a></li></ul>',2))])}const _=c(g,[["render",h]]);export{x as __pageData,_ as default};
